// === Tab: mySketch ===
// Inspired by https://www.reddit.com/r/generative/comments/v2e8jz/noise_regions_code_included/

let hw, hh;

const DEBUG = false;

const regionCount = 15;
const scaleNoiseX = 0.001;
const scaleNoiseY = 0.001;
const nbParticle = DEBUG ? 10 : 8000;
const maxLife = -1;

function setup() {
	const square = random() < 0.2;
  //createCanvas(...(square ? [min(innerWidth, innerHeight), min(innerWidth, innerHeight)] : [innerWidth, innerHeight]));
	createCanvas(1112, 834);
	setupColors();
	cmpSize();

	generateParticles();
	background(0);
}

function draw() {
	updateAndDrawParticles();
}

const cmpSize = () => {
	hh = height / 2;
	hw = width / 2;
};

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
    lapse = millis();
  } 
}


// === Tab: Particles ===
let posFct, wGen, hGen;
let drawFct;
let getRegion;
let movementByRegion;
let particles;

const generateParticles = () => {
	posFct = getRandomPositions();
	wGen = hw + random(hw);
	hGen = hh + random(hh);

	drawFct = getRandomDrawer();

	getRegion = getRandomRegion();

	movementByRegion = lspace(regionCount, () => getRandomMovement());

	particles = lspace(nbParticle, (i) => new Particle(i, nbParticle, wGen, hGen));
};

const updateAndDrawParticles = () => {
	particles = particles.filter((p, i) => {
		const isDeath = p.update(i, nbParticle);
		drawFct(p, colorsPalette);
		if (isDeath) 
			return p.reset(i, nbParticle, wGen, hGen);
		return !isDeath;
	});
};

class Particle {
  constructor(i, nb, w, h) {
		this.life = maxLife;
		this.reset(i, nb, w, h);
  }

  update() {
    this.last = this.pos.copy();
    this.pos.add(this.getMovement(this));
		return this.outOfBounds();
  }

  reset(i, nb, w, h) {
    this.pos = posFct(w, h, i, nb);
    this.last = this.pos.copy();
    this.region = this.getRegion();
		if (this.region >= movementByRegion.length) {
			this.getMovement = () => {};
			print(`Error : region isn't define in movement region list`);
		}
		this.getMovement = movementByRegion[this.region];
		return --this.life !== -1;
  }

  outOfBounds() {
    return this.region != this.getRegion() || this.pos.x < 0 || this.pos.x > width || this.pos.y < 0 || this.pos.y > height;
  }

	getRegion() {
		return getRegion(this.pos.x, this.pos.y);
	}
}

