// ---------
// Regions
// ---------
let n;

const getRandomRegion = () => {
	const noiser = random([noise, createNoise2D(), noNoise, customNoise]);
	n = (x, y) => noiser(x * scaleNoiseX, y * scaleNoiseY);
	return random([noisy(), fbm(), horizonralStripe, verticalStripe, diagonalStripe, invDiagonalStripe, spiralStripe]);
};

const noNoise = () => 0;

const customNoise = (x, y) => {
		const ix = floor(x);
		const iy = floor(y);
    const fx = fract(x);
    const fy = fract(y);

    // Four corners in 2D of a tile
    const a = random(ix, iy);
    const b = random(ix + 1, iy);
    const c = random(ix, iy + 1);
    const d = random(ix + 1, iy + 1);

    const ux = fx * fx * (3 - 2 * fx);
    const uy = fy * fy * (3 - 2 * fy);

    return lerp(a, b, ux) + (c - a) * uy * (1 - ux) + (d - b) * ux * uy;
};



const regionize = (i) => floor((regionCount - 1) * i);

const noisy = () => {
	const octaves = randInt(10);
	return (x, y) => regionize(lspace(octaves, () => n(x, y)).reduce((acc, c) => acc + c) / octaves);
}

const fbm = () => {
	var octaves = randInt(10);
	const lacunarity = 2 + random(0.5);
	const persistance = 0.5 + random(0.25);
	const redistribution = 1 + random();

	return (x, y) => {
		var result = 0, frequency = 1, amplitude = 1, maxi = amplitude;

		lspace(octaves, () => {
			result += n(x * 4, y * 4);
			frequency *= lacunarity;
			amplitude *= persistance;
			maxi += amplitude;
		});

		return regionize(constrain(pow(result, redistribution) / maxi, 0, 1));//result / octaves);
	};
}

const _norm = (x, y) => {
	const xs = x * scaleNoiseX;
	const ys = y * scaleNoiseY;
	var x0 = floor(xs);
	var y0 = floor(ys);
	return [(x0 + 1) - xs, (y0 + 1) - ys];
};

const diagonalStripe = (x, y) => {
	const [u, v] = _norm(x, y);
	return regionize(abs(u + v - n(x, y) / 2) / 2);
};

const invDiagonalStripe = (x, y) => {
	const [u, v] = _norm(x, y);
	return regionize(abs(v - u - n(x, y) / 2) / 2);
};

const horizonralStripe = (x, y) => {
	const [u, v] = _norm(x, y);
	return regionize(sin(v) * n(x, y) / 2);
};

const verticalStripe = (x, y) => {
	const [u, v] = _norm(x, y);
	return regionize(sin(u) * n(x, y) / 2);
};

const spiralStripe = (x, y) => {
	const [u, v] = _norm(x, y);
	return regionize(abs(sin(sqrt(sq(u - 0.5) + sq(v - 0.5))) * n(x, y)));
};

// ---------
// Positions
// ---------

const getRandomPositions = () => random([randomPos, randomPos, randomPos, randomInRect, randomInRect, randomOnEllipseMultiRadius]);

const randomPos = () => createVector(random(width), random(height));

const randomInRect = (w, h) => createVector(hw - w / 2 + random(w), hh - h / 2 + random(h));

const randomOnEllipseMultiRadius = (w, h, i, nb) => createVector(hw + cos(i / nbParticle * TAU) * random(w / 2), hh + sin(i / nbParticle * TAU) * random(h / 2));

// ---------
// Movements
// ---------

const getRandomMovement = () => random([
	toCenter, toOutside, mixDirection(),
	directionByRegion, topLeft, wave, stair,
	leftCurve, horizontalBracket
]);

const toCenter = (p) => p.pos.copy().sub(createVector(hw, hh)).normalize();

const toOutside = (p) => createVector(hw, hh).sub(p.pos).normalize();

const mixDirection = () => random([toCenter, toOutside]);

const directionByRegion = (p) => p5.Vector.fromAngle(p.region / regionCount * TAU).mult(0.5);

const topLeft = () => p5.Vector.fromAngle(2 * TAU / 3);

const wave = () => p5.Vector.fromAngle(PI / 3 + HALF_PI / 2 * sin(radians(frameCount * 3)));

const stair = (p) => createVector(map(cos(p.pos.x), -1, 1, 0, 1), map(cos(p.pos.y), -1, 1, 0, 1)).normalize();

const leftCurve = () => p5.Vector.fromAngle(radians(frameCount * 0.3) % HALF_PI);

const horizontalBracket = (p) => p5.Vector.fromAngle(HALF_PI + HALF_PI * (sin(map(p.pos.x, 0, width, 0, 2 * TAU))));

// ---------
// Drawer
// ---------

const getRandomDrawer = () => random([linearHue, linearHue, linearHue, uniqueColor, lerpColors]);

const _line = (p) => line(p.pos.x, p.pos.y, p.last.x, p.last.y);

const linearHue = (p) => {
	stroke((720 * p.region / regionCount) % 360, 60, 100, 4);
	strokeWeight(random(1, 2.5));
	_line(p);
};

const uniqueColor = (p, colors) => {
	stroke(colors[0]);
	strokeWeight(random(1, 2.5));
	_line(p);
};

const lerpColors = (p, colors) => {
	const [c1, c2] = colorsPalette;
	stroke(lerpColor(c1, c2, p.region / regionCount));
	strokeWeight(random(1, 2.5));
	_line(p);
};
