let colorsPalette;

const setupColors = () => {
  blendMode(ADD);
	colorMode(HSB, 360, 100, 100, 100);

	colorsPalette = random([
		[[50, 50, 100, 30], [225, 50, 100, 5]],
		[[21, 70, 100, 3], [178, 70, 100, 3]],
	]).map(c => color(...c));
};

// === Tab: util ===
const lspace = (nb, generator) => [...Array(nb).keys()].map(i => generator(i));

const randInt = nb => floor(random(nb));

